import{_ as t,o as i,c as h,a5 as c}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Admin Management — quyết định xác nhận ngày 2026-10-01","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/confirmed-decisions-2026-10-01.md","filePath":"feature/admin-management/confirmed-decisions-2026-10-01.md"}'),a={name:"feature/admin-management/confirmed-decisions-2026-10-01.md"};function e(o,n,g,d,r,u){return i(),h("div",null,[...n[0]||(n[0]=[c('<h1 id="admin-management-—-quyet-đinh-xac-nhan-ngay-2026-10-01" tabindex="-1">Admin Management — quyết định xác nhận ngày 2026-10-01 <a class="header-anchor" href="#admin-management-—-quyet-đinh-xac-nhan-ngay-2026-10-01" aria-label="Permalink to &quot;Admin Management — quyết định xác nhận ngày 2026-10-01&quot;">​</a></h1><p>Nguồn chuẩn là file Word <code>khongpush_gihub_MCP/Report/FR_3.10_Admin_Management.docx</code> cùng các quyết định người dùng đã xác nhận trong cuộc trao đổi. Bản này cập nhật nghiệp vụ và checklist, chưa chứng nhận code đã triển khai.</p><h2 id="fr-đuoc-sua" tabindex="-1">FR được sửa <a class="header-anchor" href="#fr-đuoc-sua" aria-label="Permalink to &quot;FR được sửa&quot;">​</a></h2><table tabindex="0"><thead><tr><th>FR</th><th>Chức năng</th><th>Thay đổi</th></tr></thead><tbody><tr><td>3.10.1</td><td>Thông báo</td><td>EMAIL trước; audience lúc gửi; sửa/hủy DRAFT/SCHEDULED; CANCELLED; ADMIN/USER và catalog gói.</td></tr><tr><td>3.10.2</td><td>Thống kê</td><td>Active = đăng nhập thành công; ba tiêu chí xếp hạng Agency; UTC/VN; strike hiệu lực và tiền thu.</td></tr><tr><td>3.10.4</td><td>Kiểm duyệt</td><td>Content bài theo phiên bản; ADMIN duyệt; giữ bài đã lên lịch; chặn bản cũ cho gửi bản sửa.</td></tr><tr><td>3.10.5</td><td>Trạng thái và strike</td><td>Ba Vàng quy đổi một Cam, đánh dấu nguồn; tái phạm reset 30 ngày; ba Cam chờ Admin; unflag có điều kiện; xác thực email.</td></tr><tr><td>3.10.6</td><td>Danh sách user</td><td>System role riêng với Agency; catalog gói; bộ đếm x/3, trạng thái hiệu lực/lịch sử và hạn khóa.</td></tr><tr><td>3.10.7</td><td>Tạo user</td><td>PENDING_VERIFICATION, email bắt buộc và requirePasswordReset; chỉ mở quyền sau cả hai điều kiện.</td></tr><tr><td>3.10.8</td><td>Sửa user</td><td>Email bất biến; sửa hồ sơ Owner được phép; đổi gói kỳ sau, vẫn trả tiền, không tự ghi doanh thu.</td></tr><tr><td>3.10.9</td><td>Khóa tài khoản</td><td>Admin xác nhận; khóa Owner duy nhất vẫn giữ hoạt động thành viên; đủ 30 ngày tự ACTIVE + email.</td></tr><tr><td>3.10.11</td><td>Doanh thu</td><td>MRR/ARR chuẩn hóa thuê bao; tách thu gộp/hoàn/ròng; AI Credit không vào MRR; UTC/VN.</td></tr><tr><td>3.10.12</td><td>PDF</td><td>Đồng bộ strike, trạng thái, công thức tiền và múi giờ; giữ A4, link 24 giờ và audit.</td></tr></tbody></table><p>FR <strong>3.10.3 System Health Monitoring</strong> thuộc Tuấn, không sửa Word section, ba file feature hay <code>docs/feature/admin-management/system-health</code>. FR 3.10.10 vốn không có trong tài liệu, không thêm hoặc đánh lại số. Giữ cấu trúc 8 phần của Report 3, mẫu UC của spec và checklist của task.md.</p><h2 id="quyet-đinh-dung-chung" tabindex="-1">Quyết định dùng chung <a class="header-anchor" href="#quyet-đinh-dung-chung" aria-label="Permalink to &quot;Quyết định dùng chung&quot;">​</a></h2><ul><li>System role chỉ ADMIN/USER; quyền Agency/Workspace quản lý riêng; plan đọc từ subscription catalog hiện có (BASIC/PRO/ENTERPRISE tại thời điểm đối chiếu).</li><li>Strike thay cho Trust Score: ba Vàng còn hiệu lực và chưa quy đổi tạo một Cam độc lập, bất kỳ category; ba thẻ nguồn được đánh dấu, không tái dùng. Vàng thứ tư bắt đầu nhóm mới; gỡ nguồn không gỡ Cam.</li><li>Mỗi vi phạm mới bắt đầu lại 30 ngày sạch. Hết hạn/gỡ giữ audit; không hồi sinh thẻ cũ. Ba Cam hoặc Đỏ tạo yêu cầu xét, chỉ Admin xác nhận mới DEACTIVATED. Không unflag khi chưa xử lý thẻ còn hiệu lực.</li><li>Owner duy nhất vẫn sửa hồ sơ, ghi thẻ, gắn cờ và bị khóa; thành viên khác làm việc trong quyền hiện có, thao tác chỉ Owner tạm dừng; không tự chuyển Owner/khóa Agency.</li><li>DEACTIVATED khóa cả tài khoản, thu hồi mọi session/token. Đủ 30 ngày tự ACTIVE và gửi email; quyết định này thay thế câu trả lời trước về Admin mở thủ công.</li><li>PENDING_VERIFICATION là chưa xác thực email, không phải mất Authenticator. Tài khoản Admin tạo phải xác thực email và thay mật khẩu; trước đó chỉ kích hoạt/đổi mật khẩu/đăng xuất/hỗ trợ. Không yêu cầu thiết lập lại 2FA.</li><li>Chỉ EMAIL trong đợt này. Người nhận xác định lúc gửi; sửa/hủy DRAFT/SCHEDULED; CANCELLED không gửi, SENT không thu hồi.</li><li>Báo cáo hỗ trợ UTC và Asia/Ho_Chi_Minh; lưu UTC. MRR = thuê bao trả phí hiệu lực sau giảm giá quy về tháng, gói năm /12; ARR = MRR×12. Thu gộp, hoàn và thu ròng tách riêng; AI Credit chỉ vào tiền thu. Đổi gói bởi Admin có hiệu lực kỳ sau, vẫn thanh toán, thao tác không tự ghi doanh thu.</li></ul><h2 id="quy-uoc-ky-thuat-đuoc-ghi-ro-đe-trien-khai" tabindex="-1">Quy ước kỹ thuật được ghi rõ để triển khai <a class="header-anchor" href="#quy-uoc-ky-thuat-đuoc-ghi-ro-đe-trien-khai" aria-label="Permalink to &quot;Quy ước kỹ thuật được ghi rõ để triển khai&quot;">​</a></h2><p>Các chi tiết dưới đây là cách cụ thể hóa yêu cầu, không phải tính năng sản phẩm mới: gắn quyết định kiểm duyệt với <code>contentVersionId</code>; xử lý lặp an toàn và liên kết nguồn quy đổi; không coi quy đổi là tái phạm; giữ lịch sử khi hết hạn; job bù khi gián đoạn; gửi email lỗi không hoàn tác mở khóa. Mặc định timezone báo cáo Việt Nam và chọn ba bảng xếp hạng riêng để không tự đặt trọng số.</p><h2 id="viec-can-đoi-chieu-code-trong-buoc-thiet-ke-ky-thuat" tabindex="-1">Việc cần đối chiếu code trong bước thiết kế kỹ thuật <a class="header-anchor" href="#viec-can-đoi-chieu-code-trong-buoc-thiet-ke-ky-thuat" aria-label="Permalink to &quot;Việc cần đối chiếu code trong bước thiết kế kỹ thuật&quot;">​</a></h2><ul><li>Xác định service hiện sở hữu post, version, scheduler/publisher và sự kiện moderation; không mặc định tồn tại một admin-service độc lập.</li><li>Ánh xạ chính xác nguồn sự kiện hoạt động Agency, cách đếm bài và quy thuộc doanh thu; ba tiêu chí đã chốt, chưa có công thức điểm tổng hợp.</li><li>Tận dụng auth/email/password policy, subscription billing và response/error envelope hiện có. Xác định migration SUSPENDED sang trạng thái mới mà không nhầm DELETED hoặc mở sai tài khoản.</li><li>Các endpoint/DTO trong spec là đề xuất; phải có plan.md, task.md và test.md theo feature-workflow trước code. Không coi checklist đã hoàn thành.</li></ul><h2 id="file-đong-bo" tabindex="-1">File đồng bộ <a class="header-anchor" href="#file-đong-bo" aria-label="Permalink to &quot;File đồng bộ&quot;">​</a></h2><ul><li>Word được chỉnh tại đường dẫn gốc, giữ format; 10 FR tương ứng trong <code>spec.md</code>, <code>report3_spec.md</code>, <code>report3_spec_en.md</code>.</li><li><a href="./../../BA/09-admin-management.html">BA Admin Management</a> được sửa cùng các quyết định mới, giữ nguyên dòng Monitoring.</li><li><code>data_fr_310_group_a.py</code>, <code>data_fr_310_group_b.py</code> và bản <code>_vi.py</code> được cập nhật để lần build sau không khôi phục nghiệp vụ cũ.</li><li><code>F:/LEARN/DA/task.md</code> cập nhật checklist; bản sao trước sửa ở <code>.tmp/fr310-before-20261001</code> trong workspace.</li></ul><h2 id="thay-đoi-pham-vi-ngay-2026-10-04-nguoi-dung-xac-nhan" tabindex="-1">Thay đổi phạm vi ngày 2026-10-04 (người dùng xác nhận) <a class="header-anchor" href="#thay-đoi-pham-vi-ngay-2026-10-04-nguoi-dung-xac-nhan" aria-label="Permalink to &quot;Thay đổi phạm vi ngày 2026-10-04 (người dùng xác nhận)&quot;">​</a></h2><ul><li>FR 3.10.1 thêm kênh <strong>in-app</strong> ngay trong đợt này: mỗi người nhận broadcast có một dòng <code>user_notifications</code>, ghi cùng transaction với email outbox; chuông thông báo của mọi tài khoản đọc thông báo hệ thống thật. Thay cho câu &quot;Chỉ EMAIL trong đợt này&quot; ở BR-57; FCM vẫn để giai đoạn sau. Cần cập nhật Word FR 3.10.1 tương ứng.</li><li>Thông báo nghiệp vụ workspace (duyệt bài, đăng bài, nhắc tên) vẫn là dữ liệu mẫu, thuộc FR của chủ sở hữu tương ứng.</li><li>Môi trường dev có SMTP thật: <code>ADMIN_MAIL_ALLOWED_RECIPIENTS</code> giới hạn người nhận; ngoài danh sách ghi <code>DEV_RECIPIENT_BLOCKED</code>, không gửi. Production để trống.</li></ul>',15)])])}const s=t(a,[["render",e]]);export{m as __pageData,s as default};
